#!/usr/bin/env bash
# SonicWave for Linux — installer. Adds SonicWave to your app menu with its
# own icon and opens it in its own window. Re-run any time; it's idempotent.
set -e
URL="https://sonicwave-gamma.vercel.app"
APPS="$HOME/.local/share/applications"
ICONS="$HOME/.local/share/icons/hicolor/192x192/apps"
BIN="$HOME/.local/bin"
mkdir -p "$APPS" "$ICONS" "$BIN"
# ---- icon (embedded) ----
echo "" | base64 -d > "$ICONS/sonicwave.png"
# ---- launcher ----
cat > "$BIN/sonicwave" <<'LAUNCH'
#!/usr/bin/env bash
URL="https://sonicwave-gamma.vercel.app"
for B in google-chrome google-chrome-stable chromium chromium-browser brave-browser microsoft-edge; do
  if command -v "$B" >/dev/null 2>&1; then exec "$B" --app="$URL" --start-maximized; fi
done
exec xdg-open "$URL"
LAUNCH
chmod +x "$BIN/sonicwave"
# ---- desktop entry ----
cat > "$APPS/sonicwave.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=SonicWave
Comment=Feel Every Beat — free music streaming
Exec=$BIN/sonicwave
Icon=$ICONS/sonicwave.png
Terminal=false
Categories=AudioVideo;Audio;Music;Player;
DESK
chmod +x "$APPS/sonicwave.desktop"
update-desktop-database "$APPS" 2>/dev/null || true
echo ""
echo "✔ SonicWave installed! Find it in your application menu."
echo "  Launching now…"
"$BIN/sonicwave" >/dev/null 2>&1 & disown || true
